arguments.content:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');

:root {
  --primary: #4F46E5;
  --primary-dark: #3730A3;
  --primary-light: #818CF8;
  --primary-bg: #EEF2FF;
  --accent-coral: #F97066;
  --accent-coral-dark: #DC2626;
  --accent-green: #10B981;
  --accent-green-dark: #059669;
  --accent-lime: #E6FF32;
  --bg-white: #FFFFFF;
  --bg-light: #F8FAFC;
  --bg-gray: #F1F5F9;
  --text-primary: #0F172A;
  --text-secondary: #475569;
  --text-muted: #94A3B8;
  --border-color: #E2E8F0;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 25px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 50px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.04);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --font-heading: 'Plus Jakarta Sans', 'Inter', system-ui, sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;
  --transition: 200ms ease;
  --max-width: 1200px;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--bg-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img, svg { max-width: 100%; display: block; }
a { text-decoration: none; color: inherit; }
ul, ol { list-style: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

@media (min-width: 768px) {
  .container { padding: 0 32px; }
}

@media (min-width: 1024px) {
  .container { padding: 0 48px; }
}

/* ===== NAVBAR ===== */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
  transition: box-shadow var(--transition);
}

.navbar.scrolled {
  box-shadow: var(--shadow-md);
}

.navbar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.navbar-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 1.5rem;
  color: var(--primary);
}

.navbar-logo svg {
  width: 36px;
  height: 36px;
}

.navbar-links {
  display: none;
  align-items: center;
  gap: 32px;
}

@media (min-width: 1024px) {
  .navbar-links { display: flex; }
}

.navbar-links a {
  font-size: 0.938rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--transition);
  position: relative;
}

.navbar-links a:hover,
.navbar-links a.active {
  color: var(--primary);
}

.navbar-links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--primary);
  border-radius: 1px;
}

.navbar-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.navbar-actions .btn-login {
  display: none;
  font-size: 0.938rem;
  font-weight: 500;
  color: var(--text-secondary);
  padding: 8px 16px;
  transition: color var(--transition);
}

@media (min-width: 768px) {
  .navbar-actions .btn-login { display: inline-flex; }
}

.navbar-actions .btn-login:hover {
  color: var(--primary);
}

.mobile-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  transition: background var(--transition);
}

.mobile-toggle:hover {
  background: var(--bg-gray);
}

@media (min-width: 1024px) {
  .mobile-toggle { display: none; }
}

.mobile-toggle svg {
  width: 24px;
  height: 24px;
  color: var(--text-primary);
}

.mobile-menu {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bg-white);
  padding: 24px;
  z-index: 999;
  overflow-y: auto;
}

.mobile-menu.open {
  display: block;
}

.mobile-menu a {
  display: block;
  padding: 16px 0;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--text-primary);
  border-bottom: 1px solid var(--border-color);
}

.mobile-menu a:hover {
  color: var(--primary);
}

.mobile-menu .btn-cta {
  margin-top: 24px;
  width: 100%;
  text-align: center;
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.938rem;
  padding: 12px 28px;
  border-radius: var(--radius-full);
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--primary);
  color: white;
  box-shadow: 0 2px 8px rgba(79,70,229,0.3);
}

.btn-primary:hover {
  background: var(--primary-dark);
  box-shadow: 0 4px 16px rgba(79,70,229,0.4);
  transform: translateY(-1px);
}

.btn-secondary {
  background: var(--bg-white);
  color: var(--primary);
  border: 2px solid var(--primary);
}

.btn-secondary:hover {
  background: var(--primary-bg);
  transform: translateY(-1px);
}

.btn-cta {
  background: var(--accent-coral);
  color: white;
  font-size: 1rem;
  padding: 14px 32px;
  box-shadow: 0 2px 8px rgba(249,112,102,0.3);
}

.btn-cta:hover {
  background: var(--accent-coral-dark);
  box-shadow: 0 4px 16px rgba(249,112,102,0.4);
  transform: translateY(-1px);
}

.btn-large {
  font-size: 1.063rem;
  padding: 16px 36px;
}

.btn svg {
  width: 18px;
  height: 18px;
}

/* ===== SECTIONS ===== */
.section {
  padding: 80px 0;
}

@media (min-width: 768px) {
  .section { padding: 100px 0; }
}

@media (min-width: 1024px) {
  .section { padding: 120px 0; }
}

.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 56px;
}

.section-label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--primary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 16px;
}

.section-title {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 2rem;
  line-height: 1.2;
  color: var(--text-primary);
  margin-bottom: 16px;
}

@media (min-width: 768px) {
  .section-title { font-size: 2.5rem; }
}

.section-subtitle {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--text-secondary);
}

/* ===== HERO ===== */
.hero {
  padding-top: 120px;
  padding-bottom: 60px;
  background: linear-gradient(135deg, #EEF2FF 0%, #F8FAFC 50%, #F0FDFA 100%);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(79,70,229,0.08) 0%, transparent 70%);
  border-radius: 50%;
}

.hero::after {
  content: '';
  position: absolute;
  bottom: -30%;
  left: -10%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(249,112,102,0.06) 0%, transparent 70%);
  border-radius: 50%;
}

.hero .container {
  position: relative;
  z-index: 1;
}

.hero-content {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: white;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-full);
  padding: 6px 16px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  margin-bottom: 24px;
  box-shadow: var(--shadow-sm);
}

.hero-badge svg {
  width: 16px;
  height: 16px;
  color: var(--accent-green);
}

.hero-title {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 2.5rem;
  line-height: 1.15;
  color: var(--text-primary);
  margin-bottom: 20px;
}

@media (min-width: 768px) {
  .hero-title { font-size: 3.25rem; }
}

@media (min-width: 1024px) {
  .hero-title { font-size: 3.75rem; }
}

.hero-title .highlight {
  background: linear-gradient(135deg, var(--primary), var(--primary-light));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-subtitle {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--text-secondary);
  margin-bottom: 36px;
  max-width: 640px;
  margin-left: auto;
  margin-right: auto;
}

@media (min-width: 768px) {
  .hero-subtitle { font-size: 1.25rem; }
}

.hero-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  margin-bottom: 48px;
}

@media (min-width: 480px) {
  .hero-actions {
    flex-direction: row;
    justify-content: center;
    gap: 16px;
  }
}

.hero-actions .btn {
  width: 100%;
  max-width: 240px;
}

@media (min-width: 480px) {
  .hero-actions .btn { width: auto; }
}

/* Hero tabs */
.hero-tabs {
  display: inline-flex;
  background: white;
  border-radius: var(--radius-full);
  padding: 4px;
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-sm);
  margin-bottom: 32px;
}

.hero-tab {
  padding: 10px 24px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-secondary);
  border-radius: var(--radius-full);
  transition: all var(--transition);
}

.hero-tab.active {
  background: var(--primary);
  color: white;
  box-shadow: 0 2px 8px rgba(79,70,229,0.3);
}

.hero-tab:hover:not(.active) {
  color: var(--primary);
}

.hero-preview {
  max-width: 900px;
  margin: 0 auto;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--border-color);
  background: white;
}

.hero-preview-screen {
  display: none;
  padding: 0;
}

.hero-preview-screen.active {
  display: block;
}

.preview-mockup {
  width: 100%;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 300px;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
}

@media (min-width: 768px) {
  .preview-mockup { min-height: 420px; }
}

.mockup-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 20px;
  background: rgba(255,255,255,0.1);
}

.mockup-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: rgba(255,255,255,0.3);
}

.mockup-dot:first-child { background: #FF5F56; }
.mockup-dot:nth-child(2) { background: #FFBD2E; }
.mockup-dot:nth-child(3) { background: #27C93F; }

.mockup-content {
  flex: 1;
  padding: 24px 32px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.mockup-sidebar {
  display: none;
}

@media (min-width: 768px) {
  .mockup-content {
    flex-direction: row;
    gap: 24px;
  }
  .mockup-sidebar {
    display: flex;
    flex-direction: column;
    gap: 10px;
    width: 180px;
    flex-shrink: 0;
  }
}

.mockup-sidebar-item {
  padding: 10px 14px;
  border-radius: 8px;
  background: rgba(255,255,255,0.1);
  color: rgba(255,255,255,0.7);
  font-size: 0.813rem;
  font-weight: 500;
}

.mockup-sidebar-item.active {
  background: rgba(255,255,255,0.2);
  color: white;
}

.mockup-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.mockup-card {
  background: rgba(255,255,255,0.15);
  border-radius: 10px;
  padding: 16px;
}

.mockup-card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.mockup-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.3);
}

.mockup-text-line {
  height: 10px;
  background: rgba(255,255,255,0.2);
  border-radius: 5px;
}

.mockup-text-line.short { width: 60%; }
.mockup-text-line.medium { width: 80%; }
.mockup-text-line.full { width: 100%; }

.mockup-stat-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.mockup-stat {
  background: rgba(255,255,255,0.1);
  border-radius: 8px;
  padding: 14px;
  text-align: center;
}

.mockup-stat-value {
  color: white;
  font-size: 1.25rem;
  font-weight: 700;
  font-family: var(--font-heading);
}

.mockup-stat-label {
  color: rgba(255,255,255,0.6);
  font-size: 0.75rem;
  margin-top: 4px;
}

.mockup-progress-bar {
  height: 6px;
  background: rgba(255,255,255,0.15);
  border-radius: 3px;
  margin-top: 8px;
}

.mockup-progress-fill {
  height: 100%;
  background: var(--accent-green);
  border-radius: 3px;
  width: 68%;
}

/* Student view mockup */
.preview-student .preview-mockup {
  background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
}

.student-course-cards {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}

@media (min-width: 768px) {
  .student-course-cards { grid-template-columns: repeat(3, 1fr); }
}

.student-course-card {
  background: rgba(255,255,255,0.15);
  border-radius: 10px;
  padding: 12px;
}

.student-card-thumb {
  width: 100%;
  height: 60px;
  background: rgba(255,255,255,0.15);
  border-radius: 6px;
  margin-bottom: 8px;
}

/* ===== STATS BAR ===== */
.stats-bar {
  background: var(--text-primary);
  padding: 0;
}

.stats-bar-inner {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  max-width: var(--max-width);
  margin: 0 auto;
}

@media (min-width: 640px) {
  .stats-bar-inner { grid-template-columns: repeat(3, 1fr); }
}

.stat-item {
  padding: 32px 24px;
  text-align: center;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

@media (min-width: 640px) {
  .stat-item {
    border-bottom: none;
    border-right: 1px solid rgba(255,255,255,0.1);
    padding: 40px 32px;
  }
  .stat-item:last-child { border-right: none; }
}

.stat-value {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 2.25rem;
  color: white;
  margin-bottom: 4px;
}

@media (min-width: 768px) {
  .stat-value { font-size: 2.75rem; }
}

.stat-label {
  font-size: 0.938rem;
  color: rgba(255,255,255,0.6);
  font-weight: 500;
}

/* ===== PRODUCT CARDS ===== */
.products-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 640px) {
  .products-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 1024px) {
  .products-grid { grid-template-columns: repeat(4, 1fr); }
}

.product-card {
  background: white;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}

.product-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
  border-color: var(--primary-light);
}

.product-card-icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}

.product-card-icon svg {
  width: 28px;
  height: 28px;
}

.product-card-icon.blue { background: var(--primary-bg); color: var(--primary); }
.product-card-icon.coral { background: #FEF2F2; color: var(--accent-coral); }
.product-card-icon.green { background: #ECFDF5; color: var(--accent-green); }
.product-card-icon.purple { background: #F5F3FF; color: #7C3AED; }

.product-card h3 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.25rem;
  margin-bottom: 10px;
}

.product-card p {
  font-size: 0.938rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

.product-card-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 16px;
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--primary);
  transition: gap var(--transition);
}

.product-card-link:hover {
  gap: 10px;
}

.product-card-link svg {
  width: 16px;
  height: 16px;
}

/* ===== WHY CHOOSE US (Tabs) ===== */
.why-section {
  background: var(--bg-light);
}

.why-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
  margin-bottom: 48px;
}

.why-tab {
  padding: 12px 20px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-secondary);
  background: white;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-full);
  transition: all var(--transition);
}

.why-tab.active {
  background: var(--primary);
  color: white;
  border-color: var(--primary);
  box-shadow: 0 2px 8px rgba(79,70,229,0.3);
}

.why-tab:hover:not(.active) {
  border-color: var(--primary-light);
  color: var(--primary);
}

.why-panel {
  display: none;
}

.why-panel.active {
  display: block;
}

.why-features-list {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
  max-width: 800px;
  margin: 0 auto;
}

@media (min-width: 640px) {
  .why-features-list { grid-template-columns: repeat(2, 1fr); }
}

.why-feature {
  display: flex;
  gap: 14px;
  align-items: flex-start;
  background: white;
  border-radius: var(--radius-md);
  padding: 20px;
  border: 1px solid var(--border-color);
  transition: all var(--transition);
}

.why-feature:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--primary-light);
}

.why-feature-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--primary-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.why-feature-icon svg {
  width: 20px;
  height: 20px;
  color: var(--primary);
}

.why-feature h4 {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.938rem;
  margin-bottom: 4px;
}

.why-feature p {
  font-size: 0.813rem;
  color: var(--text-secondary);
}

/* ===== FEATURE BLOCKS ===== */
.feature-block {
  display: grid;
  grid-template-columns: 1fr;
  gap: 48px;
  align-items: center;
}

@media (min-width: 768px) {
  .feature-block { grid-template-columns: 1fr 1fr; gap: 64px; }
  .feature-block.reverse .feature-visual { order: -1; }
}

.feature-text h3 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.75rem;
  margin-bottom: 16px;
  line-height: 1.3;
}

.feature-text p {
  font-size: 1.063rem;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 24px;
}

.feature-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.feature-list-item {
  display: flex;
  gap: 12px;
  align-items: flex-start;
}

.feature-list-item svg {
  width: 20px;
  height: 20px;
  color: var(--accent-green);
  flex-shrink: 0;
  margin-top: 2px;
}

.feature-list-item span {
  font-size: 0.938rem;
  color: var(--text-secondary);
}

.feature-visual {
  background: var(--bg-gray);
  border-radius: var(--radius-lg);
  padding: 32px;
  min-height: 280px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.feature-visual-card {
  background: white;
  border-radius: var(--radius-md);
  padding: 24px;
  box-shadow: var(--shadow-md);
  width: 100%;
  max-width: 320px;
}

/* ===== TESTIMONIALS ===== */
.testimonials-section {
  background: var(--bg-light);
}

.testimonials-carousel {
  position: relative;
  overflow: hidden;
}

.testimonials-track {
  display: flex;
  gap: 24px;
  transition: transform 400ms ease;
}

.testimonial-card {
  min-width: calc(100% - 0px);
  background: white;
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid var(--border-color);
  flex-shrink: 0;
}

@media (min-width: 768px) {
  .testimonial-card { min-width: calc(50% - 12px); }
}

@media (min-width: 1024px) {
  .testimonial-card { min-width: calc(33.333% - 16px); }
}

.testimonial-tag {
  display: inline-block;
  background: var(--primary-bg);
  color: var(--primary);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 4px 12px;
  border-radius: var(--radius-full);
  margin-bottom: 16px;
}

.testimonial-quote {
  font-size: 1rem;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 20px;
  font-style: italic;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary-light), var(--primary));
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: 700;
  font-size: 1rem;
  font-family: var(--font-heading);
}

.testimonial-name {
  font-weight: 600;
  font-size: 0.938rem;
}

.testimonial-role {
  font-size: 0.813rem;
  color: var(--text-muted);
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: white;
  border: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  box-shadow: var(--shadow-sm);
}

.carousel-btn:hover {
  background: var(--primary);
  color: white;
  border-color: var(--primary);
}

.carousel-btn svg {
  width: 20px;
  height: 20px;
}

.carousel-dots {
  display: flex;
  gap: 8px;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--border-color);
  transition: all var(--transition);
}

.carousel-dot.active {
  background: var(--primary);
  width: 24px;
  border-radius: 4px;
}

/* ===== PRICING ===== */
.pricing-section {
  background: var(--bg-white);
}

.pricing-header-note {
  font-size: 0.938rem;
  color: var(--text-secondary);
  text-align: center;
  margin-bottom: 48px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.pricing-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
  max-width: 900px;
  margin: 0 auto;
}

@media (min-width: 768px) {
  .pricing-grid { grid-template-columns: repeat(2, 1fr); }
}

.pricing-card {
  background: white;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
  position: relative;
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
}

.pricing-card.featured {
  border-color: var(--primary);
  box-shadow: 0 0 0 1px var(--primary), var(--shadow-lg);
}

.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: white;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 4px 16px;
  border-radius: var(--radius-full);
}

.pricing-plan-name {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.25rem;
  margin-bottom: 8px;
}

.pricing-plan-desc {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: 20px;
}

.pricing-price {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 2.5rem;
  margin-bottom: 4px;
}

.pricing-price span {
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-muted);
}

.pricing-note {
  font-size: 0.813rem;
  color: var(--text-muted);
  margin-bottom: 24px;
}

.pricing-features {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 24px;
}

.pricing-feature {
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.pricing-feature svg {
  width: 18px;
  height: 18px;
  color: var(--accent-green);
  flex-shrink: 0;
}

.pricing-card .btn {
  width: 100%;
}

.enterprise-card {
  background: linear-gradient(135deg, var(--text-primary), #1E293B);
  color: white;
  border-color: transparent;
  text-align: center;
  padding: 48px 32px;
}

.enterprise-card .pricing-plan-name,
.enterprise-card .pricing-plan-desc {
  color: rgba(255,255,255,0.8);
}

.enterprise-card .pricing-plan-name {
  color: white;
}

.enterprise-features {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  margin: 24px 0;
}

.enterprise-feature-tag {
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.15);
  border-radius: var(--radius-full);
  padding: 6px 16px;
  font-size: 0.813rem;
  color: rgba(255,255,255,0.8);
}

/* ===== INTEGRATIONS ===== */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

@media (min-width: 640px) {
  .integrations-grid { grid-template-columns: repeat(4, 1fr); }
}

@media (min-width: 768px) {
  .integrations-grid { grid-template-columns: repeat(6, 1fr); }
}

.integration-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 20px 12px;
  background: white;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  transition: all var(--transition);
}

.integration-item:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--primary-light);
  transform: translateY(-2px);
}

.integration-icon {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
}

.integration-icon svg {
  width: 32px;
  height: 32px;
}

.integration-name {
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--text-secondary);
  text-align: center;
}

/* ===== FAQ ===== */
.faq-section {
  background: var(--bg-light);
}

.faq-list {
  max-width: 720px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.faq-item {
  background: white;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: all var(--transition);
}

.faq-item:hover {
  border-color: var(--primary-light);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  width: 100%;
  padding: 20px 24px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  text-align: left;
  cursor: pointer;
}

.faq-question svg {
  width: 20px;
  height: 20px;
  color: var(--text-muted);
  flex-shrink: 0;
  transition: transform var(--transition);
}

.faq-item.open .faq-question svg {
  transform: rotate(180deg);
}

.faq-item.open .faq-question {
  color: var(--primary);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease;
}

.faq-answer-inner {
  padding: 0 24px 20px;
  font-size: 0.938rem;
  color: var(--text-secondary);
  line-height: 1.7;
}

/* ===== CTA BANNER ===== */
.cta-banner {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  padding: 80px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-banner::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -10%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(255,255,255,0.08) 0%, transparent 70%);
  border-radius: 50%;
}

.cta-banner .container {
  position: relative;
  z-index: 1;
}

.cta-banner h2 {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 2rem;
  color: white;
  margin-bottom: 16px;
}

@media (min-width: 768px) {
  .cta-banner h2 { font-size: 2.5rem; }
}

.cta-banner p {
  color: rgba(255,255,255,0.8);
  font-size: 1.125rem;
  margin-bottom: 32px;
  max-width: 560px;
  margin-left: auto;
  margin-right: auto;
}

.cta-banner .btn {
  background: white;
  color: var(--primary);
  font-size: 1.063rem;
  padding: 16px 36px;
}

.cta-banner .btn:hover {
  background: var(--bg-gray);
  box-shadow: var(--shadow-lg);
}

/* ===== SOCIAL PROOF BAR ===== */
.social-proof {
  padding: 60px 0;
  text-align: center;
}

.social-proof-text {
  font-size: 0.938rem;
  color: var(--text-muted);
  margin-bottom: 24px;
  font-weight: 500;
}

.social-proof-logos {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 32px;
  opacity: 0.5;
}

.social-proof-logo {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--text-secondary);
}

/* ===== FOOTER ===== */
.footer {
  background: var(--text-primary);
  color: rgba(255,255,255,0.6);
  padding: 80px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 40px;
  margin-bottom: 48px;
}

@media (min-width: 640px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 1024px) {
  .footer-grid { grid-template-columns: 2fr repeat(4, 1fr); }
}

.footer-brand {
  max-width: 280px;
}

.footer-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 1.5rem;
  color: white;
  margin-bottom: 16px;
}

.footer-logo svg {
  width: 32px;
  height: 32px;
}

.footer-desc {
  font-size: 0.875rem;
  line-height: 1.7;
  margin-bottom: 20px;
}

.footer-social {
  display: flex;
  gap: 12px;
}

.footer-social a {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
}

.footer-social a:hover {
  background: var(--primary);
  color: white;
}

.footer-social a svg {
  width: 18px;
  height: 18px;
}

.footer-col h4 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.875rem;
  color: white;
  margin-bottom: 20px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer-col a {
  display: block;
  font-size: 0.875rem;
  padding: 6px 0;
  transition: color var(--transition);
}

.footer-col a:hover {
  color: white;
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  font-size: 0.813rem;
}

@media (min-width: 768px) {
  .footer-bottom {
    flex-direction: row;
    justify-content: space-between;
  }
}

.footer-bottom-links {
  display: flex;
  gap: 24px;
}

.footer-bottom-links a:hover {
  color: white;
}

/* ===== THREE STEPS ===== */
.steps-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 32px;
  counter-reset: step;
}

@media (min-width: 768px) {
  .steps-grid { grid-template-columns: repeat(3, 1fr); }
}

.step-card {
  background: white;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 32px;
  text-align: center;
  counter-increment: step;
  position: relative;
  transition: all var(--transition);
}

.step-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.step-number {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--primary);
  color: white;
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
}

.step-card h3 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.125rem;
  margin-bottom: 10px;
}

.step-card p {
  font-size: 0.938rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ===== TOOLS GRID ===== */
.tools-container {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .tools-container { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 1024px) {
  .tools-container { grid-template-columns: repeat(5, 1fr); }
}

.tools-category {
  background: white;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 24px;
}

.tools-category h4 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.938rem;
  margin-bottom: 14px;
  color: var(--primary);
}

.tools-category ul {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.tools-category li {
  font-size: 0.813rem;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.tools-category li::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent-green);
  flex-shrink: 0;
}

/* ===== FILE TYPES GRID ===== */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

@media (min-width: 640px) {
  .file-types-grid { grid-template-columns: repeat(3, 1fr); }
}

@media (min-width: 768px) {
  .file-types-grid { grid-template-columns: repeat(4, 1fr); }
}

.file-type-card {
  background: white;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 24px;
  text-align: center;
  transition: all var(--transition);
}

.file-type-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.file-type-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  background: var(--primary-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 12px;
}

.file-type-icon svg {
  width: 24px;
  height: 24px;
  color: var(--primary);
}

.file-type-card h4 {
  font-size: 0.875rem;
  font-weight: 600;
}

/* ===== RESOURCES ===== */
.resources-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .resources-grid { grid-template-columns: repeat(3, 1fr); }
}

.resource-card {
  background: white;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition);
}

.resource-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.resource-thumb {
  height: 160px;
  background: linear-gradient(135deg, var(--primary-bg), #F0FDFA);
  display: flex;
  align-items: center;
  justify-content: center;
}

.resource-thumb svg {
  width: 48px;
  height: 48px;
  color: var(--primary);
  opacity: 0.5;
}

.resource-body {
  padding: 24px;
}

.resource-body h4 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1rem;
  margin-bottom: 8px;
  line-height: 1.4;
}

.resource-body p {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 16px;
}

.resource-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--primary);
}

.resource-link svg {
  width: 16px;
  height: 16px;
}

/* ===== SPOTLIGHT GRID ===== */
.spotlight-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .spotlight-grid { grid-template-columns: repeat(3, 1fr); }
}

.spotlight-card {
  background: white;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
}

.spotlight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.spotlight-card h4 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.125rem;
  margin-bottom: 10px;
}

.spotlight-card p {
  font-size: 0.938rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ===== MEMBERSHIP FEATURES ===== */
.membership-features {
  display: grid;
  grid-template-columns: 1fr;
  gap: 32px;
}

@media (min-width: 768px) {
  .membership-features { grid-template-columns: repeat(3, 1fr); }
}

.membership-feature {
  text-align: center;
  padding: 32px 24px;
  background: white;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  transition: all var(--transition);
}

.membership-feature:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.membership-stat {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 2.5rem;
  color: var(--primary);
  margin-bottom: 8px;
}

.membership-feature h4 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.125rem;
  margin-bottom: 10px;
}

.membership-feature p {
  font-size: 0.938rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ===== AI SECTION ===== */
.ai-section {
  background: linear-gradient(135deg, #0F172A, #1E293B);
  color: white;
}

.ai-section .section-title {
  color: white;
}

.ai-section .section-subtitle {
  color: rgba(255,255,255,0.7);
}

.ai-features-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
}

@media (min-width: 640px) {
  .ai-features-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 1024px) {
  .ai-features-grid { grid-template-columns: repeat(3, 1fr); }
}

.ai-feature-card {
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-md);
  padding: 24px;
  transition: all var(--transition);
}

.ai-feature-card:hover {
  background: rgba(255,255,255,0.08);
  border-color: rgba(255,255,255,0.2);
  transform: translateY(-2px);
}

.ai-feature-card h4 {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.938rem;
  margin-bottom: 6px;
  color: white;
}

.ai-feature-card p {
  font-size: 0.813rem;
  color: rgba(255,255,255,0.6);
}

/* ===== GLOBAL SCALE ===== */
.global-visual {
  background: var(--bg-gray);
  border-radius: var(--radius-lg);
  padding: 48px;
  text-align: center;
  position: relative;
}

.global-map-placeholder {
  width: 100%;
  max-width: 600px;
  margin: 0 auto;
  aspect-ratio: 2/1;
  background: linear-gradient(135deg, var(--primary-bg) 0%, #F0FDFA 100%);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.map-dots {
  position: absolute;
  inset: 0;
}

